<?php
namespace App\Http\Controllers\Api;
use App\Models\User;use App\Models\Vehicle;use App\Models\UserVehicle;use Illuminate\Http\Request;
class VehicleController{private function u(Request $r){return User::findOrFail($r->session()->get('user_id'));}public function index(Request $r){$u=$this->u($r);return $u->role==='resident'?Vehicle::where('resident_id',$u->id)->get():UserVehicle::where('user_id',$u->id)->get();}public function store(Request $r){$u=$this->u($r);$d=$r->validate(['plate_number'=>'required|string|max:32','vehicle_type'=>'required|string|max:32','color'=>'nullable|string|max:64']);$d['color']=ucwords(strtolower($d['color']??''));if($u->role==='resident'){abort_if(Vehicle::where('resident_id',$u->id)->count()>=10,422,'Vehicle limit reached.');$d['resident_id']=$u->id;return Vehicle::create($d);}abort_unless(in_array($u->role,['guard','admin','super_admin']),403);abort_if(UserVehicle::where('user_id',$u->id)->count()>=5,422,'Vehicle limit reached.');$d['user_id']=$u->id;return UserVehicle::create($d);}public function destroy(Request $r,$id){$u=$this->u($r);$m=$u->role==='resident'?Vehicle::where('resident_id',$u->id)->findOrFail($id):UserVehicle::where('user_id',$u->id)->findOrFail($id);$m->delete();return ['ok'=>true];}}
